/* <style> */
*, ::before, ::after { box-sizing: border-box; }
body { margin: 0px; font-family: Inter, system-ui, sans-serif; color: rgb(26, 29, 36); }
h1, h2, h3, p { margin: 0px; }
.page { display: flex; flex-direction: column; }
.nav-outer { }
.nav-mid { }
.nav { display: flex; align-items: center; justify-content: space-between; padding: 16px 32px; border-bottom: 1px solid rgb(228, 230, 235); }
.brand { display: flex; align-items: baseline; font-weight: 700; font-size: 18px; letter-spacing: -0.01em; }
.brand b { color: rgb(45, 74, 124); }
.brand sup { font-size: 10px; }
.nav-links { display: flex; gap: 24px; list-style: none; margin: 0px; padding: 0px; }
.nav-links a { color: rgb(74, 80, 89); text-decoration: none; font-size: 14px; }
.hero { display: flex; flex-direction: column; align-items: center; gap: 20px; padding: 96px 32px; background-image: linear-gradient(rgb(251, 251, 253), rgb(242, 244, 248)); }
.eyebrow { font-size: 12px; font-weight: 600; letter-spacing: 0.12em; text-transform: uppercase; color: rgb(45, 74, 124); }
.hero h1 { font-size: 56px; line-height: 1.05; letter-spacing: -0.03em; max-width: 16ch; text-align: center; }
.hero h1 .mark { background: rgb(217, 232, 255); color: rgb(22, 34, 58); padding: 0px 8px; border-radius: 6px; display: inline-block; }
.plain-span { }
.hero p { font-size: 18px; line-height: 1.6; color: rgb(74, 80, 89); max-width: 52ch; text-align: center; }
.cta { display: flex; gap: 12px; }
.btn { padding: 12px 22px; border-radius: 8px; border: 1px solid rgb(45, 74, 124); background: rgb(45, 74, 124); color: rgb(255, 255, 255); font-size: 15px; font-weight: 600; }
.btn-ghost { background: transparent; color: rgb(45, 74, 124); }
.badge::before { content: "★"; margin-right: 6px; color: rgb(217, 179, 106); }
.badge { display: inline-flex; align-items: center; font-size: 13px; color: rgb(118, 125, 136); }
.features { display: flex; gap: 24px; padding: 64px 32px; }
.card { flex: 1 1 0px; display: flex; flex-direction: column; gap: 10px; padding: 24px; border: 1px solid rgb(228, 230, 235); border-radius: 12px; background: rgb(255, 255, 255); }
.card h3 { font-size: 17px; font-weight: 600; }
.card p { font-size: 14px; line-height: 1.55; color: rgb(74, 80, 89); }
.shot { width: 100%; height: 120px; object-fit: cover; border-radius: 8px; }
.footer { padding: 32px; border-top: 1px solid rgb(228, 230, 235); color: rgb(118, 125, 136); font-size: 13px; }
.legal { font-size: 11px; line-height: 15.4px; color: rgb(118, 125, 136); letter-spacing: 1.32px; }
.fineprint { display: block; font-style: italic; font-size: 10px; line-height: 14.5px; margin-top: 6px; max-width: 40ch; }
.mobile-menu { display: none; }
.with-icon { display: flex; align-items: center; gap: 8px; }
.with-icon .ico { display: inline; color: rgb(45, 74, 124); }
.just-words { font-size: 12px; color: rgb(118, 125, 136); }
.chip-row { display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; border: 1px solid rgb(228, 230, 235); }
.icon-row { display: flex; align-items: center; gap: 8px; color: rgb(45, 74, 124); }
.icon-row svg { width: 20px; height: 20px; fill: currentcolor; }
.icon-row svg.icon-fixed { fill: rgb(217, 179, 106); }
.gradient-title { background-image: linear-gradient(90deg, rgb(45, 74, 124), rgb(217, 179, 106)); background-clip: text; -webkit-text-fill-color: transparent; font-size: 32px; }
.content-box { box-sizing: content-box; width: 200px; height: 40px; padding: 12px 16px; border: 2px solid rgb(45, 74, 124); }
@media (max-width: 768px) {
  .hero { padding: 56px 20px; }
  .hero h1 { font-size: 36px; }
  .features { flex-direction: column; gap: 16px; }
  .nav { padding: 12px 20px; }
}
@media (max-width: 390px) {
  .hero h1 { font-size: 28px; }
  .hero p { font-size: 15px; }
  .card { padding: 16px; }
}
